(()=>{
 'use strict';let apps=[];
 const platform=window.YamaNative?.platform;
 if(platform==='windows'){document.body.classList.add('native-desktop');const bar=document.createElement('div');bar.className='window-titlebar';bar.innerHTML='<div class="window-brand"><img src="assets/yamaportal.png" alt=""><span>Yamaportal</span></div><div class="window-controls"><button data-window="minimize" aria-label="Minimalizovat">−</button><button data-window="maximize" aria-label="Maximalizovat nebo obnovit">□</button><button data-window="close" aria-label="Zavřít okno">×</button></div>';document.body.prepend(bar);}
 document.addEventListener('click',event=>{const button=event.target.closest('[data-window]');if(button&&platform==='windows')void YamaNative.windowAction(button.dataset.window);});
 function markup(id){if(!window.YamaNative||!['chat','search','help'].includes(id))return '';const installed=apps.find(app=>app.id===id)?.installed;if(platform==='android'){if(id!=='search')return '';return `<div class="app-actions"><button class="secondary" data-android-launch="search" ${installed?'':'disabled'}>${installed?'Otevřít YamaSearch':'YamaSearch není nainstalovaný'}</button></div><p class="caption" id="native-search" role="status">${installed?'Otevře nainstalovaný YamaSearch. Návrat: v nabídce YamaSearch zvol „Zpět do Yamaportalu“.':'Na tomto zařízení není ověřená instalace YamaSearch.'}</p>`;}if(platform!=='windows')return '';return `<div class="app-actions"><button class="secondary" data-native-launch="${id}" ${installed?'':'disabled'}>Spustit nainstalovanou aplikaci</button><button class="secondary" data-native-choose="${id}">Vybrat instalovanou / portable verzi</button></div><p class="caption" id="native-${id}" role="status">${installed?'Dostupná v tomto počítači. Přihlášení do Portalu není potřeba.':'Vyber existující aplikaci v tomto počítači.'} ${id==='chat'?'Samotný Yamachat vyžaduje přihlášení a internet. ':''}Návrat do Portalu: Ctrl+Shift+P nebo jeho ikona na hlavním panelu.</p>`;}
 async function refresh(){if(!window.YamaNative)return;try{apps=await YamaNative.apps();document.dispatchEvent(new CustomEvent('yama-native-state'));}catch{}}
 document.addEventListener('click',async event=>{const android=event.target.closest('[data-android-launch]');const launch=event.target.closest('[data-native-launch]');const choose=event.target.closest('[data-native-choose]');if(!android&&!launch&&!choose)return;const button=android||launch||choose;const id=button.dataset.androidLaunch||button.dataset.nativeLaunch||button.dataset.nativeChoose;const status=document.querySelector('#native-'+id);button.disabled=true;try{if(android){await YamaNative.launch(id);if(status)status.textContent='YamaSearch se otevřel. Návrat: v jeho nabídce zvol „Zpět do Yamaportalu“.';}else if(choose){await YamaNative.choose(id);await refresh();}else{await YamaNative.launch(id);if(status)status.textContent='Aplikace byla spuštěna. Zpět do Portalu: Ctrl+Shift+P nebo jeho ikona na hlavním panelu.';}}catch(error){if(status)status.textContent=error?.message||'Aplikaci se nepodařilo otevřít. Zkontroluj, že je nainstalovaná, a zkus to znovu.';}finally{button.disabled=false;}});
 window.YamaNativeUI={markup,refresh};void refresh();
})();
